// ========================================================
// 🔍 استخراج بيانات الرسالة وكشف طلب العنصر البشري (Regex)
// ========================================================

const raw = $input.first().json;
const body = raw.body || raw;

// استخراج نص الرسالة وبيانات العميل
const message = (body.message || body.text || body.Body || body.content || '').toString().trim();
const customerName = (body.customerName || body.name || body.ProfileName || 'العميل').toString().trim();
const customerPhone = (body.phone || body.from || body.From || body.sender || '').toString().trim();
const conversationId = (body.conversationId || body.chatId || body.id || Date.now().toString()).toString();

// قاموس الكلمات الدالة على طلب موظف بشري (عربي + إنجليزي)
const humanPatterns = [
  /خدم[ةه]\s*العملا[ءإ]/,
  /عنصر\s*بشر[يى]/,
  /موظف/,
  /بشر[يى]/,
  /إنسان|انسان/,
  /شخص\s*(حقيقي)?/,
  /آدمي|ادمي/,
  /حولن[يى]/,
  /أبغ[يى]\s*(أ)?كلم/,
  /ابغ[يى]\s*(ا)?كلم/,
  /عايز\s*(أ)?كلم/,
  /عاوز\s*(أ)?كلم/,
  /بدي\s*احك[يى]/,
  /تحدث\s*مع/,
  /محادث[ةه]\s*بشر/,
  /اتصال\s*بشر/,
  /كلمني\s*حد/,
  /ابي\s*احد/,
  /مسؤول/,
  /مدير/,
  /\bhuman\b/i,
  /\bagent\b/i,
  /\brepresentative\b/i,
  /\bsupport\s*team\b/i,
  /\breal\s*person\b/i,
  /\blive\s*agent\b/i
];

const humanRequested = humanPatterns.some(pattern => pattern.test(message));

return [{
  json: {
    message,
    customerName,
    customerPhone,
    conversationId,
    humanRequested,
    timestamp: new Date().toISOString()
  }
}];

// ========================================================
// 🛑 إيقاف الـ AI + تجهيز رد التحويل البشري والتنبيه الداخلي
// ========================================================

const data = $input.first().json;

// الرد الذي سيصل للعميل
const customerReply = `أهلاً بك ${data.customerName} 👋\n\nتم تحويل محادثتك لفريق خدمة العملاء، وسيقوم أحد ممثلينا بالتواصل معك والرد عليك في أقرب وقت.\n\nشكراً لصبرك 🙏`;

// التنبيه الداخلي للموظفين (لا يصل للعميل أبداً)
const internalAlert = `🚨 طلب موظف بشري عاجل\n━━━━━━━━━━━━━━━━━\n👤 العميل: ${data.customerName}\n📱 الرقم: ${data.customerPhone || 'غير محدد'}\n💬 الرسالة: "${data.message}"\n⏰ الوقت: ${new Date().toLocaleTimeString('ar-SA')}\n\n📌 الإجراء المطلوب:\nيرجى فتح المحادثة والرد على العميل مباشرة.`;

return [{
  json: {
    ...data,
    action: 'human_handoff',
    aiStopped: true,
    replyToCustomer: customerReply,
    internalAlert: internalAlert,
    supervisorSentiment: 'neutral'
  }
}];

