// ========================================================
// 📊 تحليل قرار المشرف الذكي وتحديد مسار التصعيد
// ========================================================

const prev = $('🔍 2. فحص طلب موظف بشري فوراً').first().json;
const httpResult = $input.first().json;

let supervisor = {
  sentiment: 'neutral',
  shouldEscalate: false,
  escalationReason: null,
  purchaseIntent: 'none',
  suggestedAction: 'رد تلقائي عادي',
  suggestedInternalNote: null,
  confidence: 0.8
};

try {
  const content = httpResult.choices?.[0]?.message?.content || '{}';
  const parsed = JSON.parse(content);
  supervisor = { ...supervisor, ...parsed };
} catch (e) {
  // في حال فشل التحليل استخدم الإعدادات التلقائية
}

// قواعد حسم التصعيد (بوابة الأمان)
const isAngry = supervisor.sentiment === 'angry';
const needsEscalation = (
  supervisor.confidence >= 0.70 &&
  (supervisor.shouldEscalate === true || isAngry)
);

return [{
  json: {
    ...prev,
    supervisor,
    needsEscalation
  }
}];

// ========================================================
// 🚨 تجهيز رد اعتذاري للعميل وتنبيه غضب داخلي للموظفين
// ========================================================

const data = $input.first().json;
const sv = data.supervisor;

// الرد الموجه للعميل (مهدئ ومحترف دون ذكر أي كواليس)
const customerReply = `أهلاً بك ${data.customerName} 🙏\n\nنتفهم تماماً استياءك ونأسف لأي تجربة غير مرضية. تم تصعيد محادثتك فوراً لمسؤول خدمة العملاء وسيقوم بمراجعة الأمر والتواصل معك مباشرة لمعالجة مشكلتك بأفضل شكل.\n\nنقدّر صبرك معنا.`;

// التنبيه الداخلي للموظفين (عزل تام P0 Isolation)
const internalAlert = `🚨 تنبيه تصعيد: عميل غاضب / استياء كبير\n━━━━━━━━━━━━━━━━━━━━━━━━━━━\n👤 العميل: ${data.customerName}\n📱 الرقم: ${data.customerPhone || 'غير محدد'}\n😡 الشعور: ${sv.sentiment}\n📋 سبب التصعيد: ${sv.escalationReason || 'استياء عالي من الخدمة'}\n💡 التوجيه للموظف: ${sv.suggestedAction || 'التواصل فوراً وحل المشكلة'}\n💬 الرسالة: "${data.message}"\n⏰ الوقت: ${new Date().toLocaleTimeString('ar-SA')}\n🔒 نسبة الثقة: ${(sv.confidence * 100).toFixed(0)}%`;

return [{
  json: {
    ...data,
    action: 'escalation',
    aiStopped: true,
    replyToCustomer: customerReply,
    internalAlert: internalAlert
  }
}];

