// ========================================================
// 🛡️ فلتر الأمان الصارم (منع تسريب الملاحظات الداخلية P0)
// ========================================================

const prev = $('❓ 7. هل العميل غاضب أو يحتاج تصعيد؟').first().json;
const httpResult = $input.first().json;

let reply = 'أهلاً بك! شكراً لتواصلك معنا، كيف نقدر نساعدك اليوم؟';

try {
  reply = httpResult.choices?.[0]?.message?.content || reply;
} catch (e) {
  // في حال وجود مشكلة
}

// كلمات محظورة تمنع خروج أي نوت داخلي للعميل
const leakPatterns = [
  /AI Supervisor/i,
  /تنبيه تصعيد/,
  /ملاحظة داخلية/,
  /التوجيه للموظف/,
  /internal note/i,
  /🚨/,
  /شعور العميل/,
  /سبب التصعيد/
];

const isLeaked = leakPatterns.some(p => p.test(reply));

if (isLeaked) {
  // استبدال فوري لحماية النظام
  reply = `أهلاً بك ${prev.customerName} 👋\nشكراً لتواصلك معنا! تم استلام رسالتك وسيتم الرد عليك في أقرب وقت.`;
}

// هل هناك نية شراء عالية تحتاج تنبيه الفريق الداخلي؟
let internalAlert = null;
if (prev.supervisor?.purchaseIntent === 'high_intent') {
  internalAlert = `🎯 فرصة بيع جديدة (High Intent)\n━━━━━━━━━━━━━━━━━━━━\n👤 العميل: ${prev.customerName}\n📱 الرقم: ${prev.customerPhone || 'غير محدد'}\n💬 الرسالة: "${prev.message}"\n💡 العميل مهتم بالشراء/الطلب الآن، يُفضل متابعته.`;
}

return [{
  json: {
    ...prev,
    action: 'ai_reply',
    aiStopped: false,
    replyToCustomer: reply,
    internalAlert: internalAlert
  }
}];
